global.set('device_alive', true);
const topic = 'spBv1.0/FactoryPlus/DBIRTH/Virtual_Gateway_NodeRED/Simulated_CNC_01';
const spbBirthPayload = {
    timestamp: Date.now(),
    metrics: [
        { name: 'Asset_ID',          string_value: 'Simulated_CNC_01',  datatype: 12 },
        { name: 'firmware_version',  string_value: 'v3.2.0-industrial', datatype: 12 },
        { name: 'serial_number',     string_value: 'SN-CNC-8832',       datatype: 12 },
        { name: 'max_temp_threshold',double_value: 85.0,                datatype: 10 },
        { name: 'safety_interlock',  boolean_value: true,               datatype: 11 }
    ],
    seq: 0
};
return { topic: topic, payload: JSON.stringify(spbBirthPayload), qos: 0, retain: false };

if (global.get('device_alive') === false) {
    return null;
}
const topic = 'spBv1.0/FactoryPlus/DDATA/Virtual_Gateway_NodeRED/Simulated_CNC_01';
const tempOverride = global.get('temp_override');
const currentTemp = tempOverride !== undefined ? tempOverride : +(42.0 + Math.sin(Date.now() / 6000) * 5.0 + (Math.random() * 1.5)).toFixed(2);
const statusVal = global.get('status_override') || 'RUNNING';
const safetyVal = global.get('safety_override') !== undefined ? global.get('safety_override') : true;

const spbDataPayload = {
    timestamp: Date.now(),
    metrics: [
        { name: 'Asset_ID',    string_value: 'Simulated_CNC_01', datatype: 12 },
        { name: 'temperature', double_value: currentTemp,        datatype: 10 },
        { name: 'vibration',   double_value: 1.45,                datatype: 10 },
        { name: 'status',      string_value: statusVal,          datatype: 12 },
        { name: 'safety_ok',   boolean_value: safetyVal,         datatype: 11 }
    ],
    seq: Math.floor(Math.random() * 255)
};
return { topic: topic, payload: JSON.stringify(spbDataPayload), qos: 0, retain: false };

global.set('device_alive', false);
const topic = 'spBv1.0/FactoryPlus/DDEATH/Virtual_Gateway_NodeRED/Simulated_CNC_01';
const spbDeathPayload = {
    timestamp: Date.now(),
    metrics: [
        { name: 'Asset_ID', string_value: 'Simulated_CNC_01', datatype: 12 }
    ],
    seq: Math.floor(Math.random() * 255)
};
return { topic: topic, payload: JSON.stringify(spbDeathPayload), qos: 0, retain: false };

global.set('device_alive', true);
global.set('temp_override', 95.0);
global.set('status_override', 'ALARM_OVERHEAT');
global.set('safety_override', false);

const topic = 'spBv1.0/FactoryPlus/DDATA/Virtual_Gateway_NodeRED/Simulated_CNC_01';
const spbAlertPayload = {
    timestamp: Date.now(),
    metrics: [
        { name: 'Asset_ID',    string_value: 'Simulated_CNC_01', datatype: 12 },
        { name: 'temperature', double_value: 95.0,                datatype: 10 },
        { name: 'vibration',   double_value: 8.92,                datatype: 10 },
        { name: 'status',      string_value: 'ALARM_OVERHEAT',   datatype: 12 },
        { name: 'safety_ok',   boolean_value: false,              datatype: 11 }
    ],
    seq: Math.floor(Math.random() * 255)
};
return { topic: topic, payload: JSON.stringify(spbAlertPayload), qos: 0, retain: false };

global.set('device_alive', true);
global.set('temp_override', undefined);
global.set('status_override', 'RUNNING');
global.set('safety_override', true);

